<?php
declare(strict_types=1);
namespace App;

/**
 * Public legal pages (/privacidad, /terminos), rendered on the server so crawlers (Meta app review, search engines) read
 * them without JavaScript. The responsible party comes from LEGAL_* in the .env; nothing is invented when it is missing.
 * Colombian framework: Ley 1581 de 2012, Decreto 1074 de 2015 (Decreto 1377 de 2013) and Ley 1480 de 2011.
 */
final class LegalPages {
 public const UPDATED='26 de octubre de 2026';

 /** @return array{name:string,id:string,address:string,email:string,site:string} */
 private static function owner(): array {
  $email=Support::env('LEGAL_EMAIL');if(!filter_var($email,FILTER_VALIDATE_EMAIL))$email=Support::env('MAIL_FROM_ADDRESS');if(!filter_var($email,FILTER_VALIDATE_EMAIL))$email='';
  $site=rtrim(Support::env('APP_URL'),'/');
  return ['name'=>trim(Support::env('LEGAL_NAME'))?:'Tinbana','id'=>trim(Support::env('LEGAL_ID')),'address'=>trim(Support::env('LEGAL_ADDRESS')),'email'=>$email,'site'=>preg_match('~^https?://[^/\s]+$~',$site)?$site:''];
 }
 private static function contact(array $o): string {
  return $o['email']!==''?'<a href="mailto:'.Support::escape($o['email']).'">'.Support::escape($o['email']).'</a>':'los canales de contacto publicados en la plataforma';
 }
 private static function identity(array $o): string {
  $rows=['Responsable'=>$o['name']];if($o['id']!=='')$rows['Identificación']=$o['id'];if($o['address']!=='')$rows['Domicilio']=$o['address'];
  if($o['email']!=='')$rows['Correo de contacto']=$o['email'];if($o['site']!=='')$rows['Sitio web']=$o['site'];
  $html='<dl class="legal-identity">';foreach($rows as $k=>$v)$html.='<div><dt>'.$k.'</dt><dd>'.($k==='Correo de contacto'?self::contact($o):Support::escape($v)).'</dd></div>';return $html.'</dl>';
 }

 public static function privacy(): string {
  $o=self::owner();$n=Support::escape($o['name']);$c=self::contact($o);
  return self::page('privacidad','Política de privacidad y tratamiento de datos','Cómo recogemos, usamos y protegemos los datos personales en Tinbana, y cómo puedes ejercer tus derechos.',[
   ['responsable','Quién es responsable','<p>Esta política explica cómo '.$n.' («Tinbana», «nosotros») trata los datos personales en la plataforma Tinbana, conforme a la Ley 1581 de 2012, el Decreto 1074 de 2015 y demás normas colombianas de protección de datos personales.</p>'.self::identity($o)],
   ['roles','Nuestro papel según el tipo de dato','<p>Tinbana es una herramienta para tiendas de dropshipping. Por eso actuamos en dos papeles distintos:</p><ul><li><strong>Responsables</strong> de los datos de las personas que crean una cuenta en Tinbana (las «tiendas» o «usuarios»).</li><li><strong>Encargados</strong> de los datos de los clientes de cada tienda: quienes llenan un formulario en una landing, hacen un pedido o escriben por WhatsApp a una tienda. En ese caso, la tienda es la responsable del tratamiento y decide para qué usa esos datos; nosotros los tratamos por cuenta suya y según sus instrucciones.</li></ul><p>Si eres cliente de una tienda y quieres ejercer tus derechos, puedes dirigirte a la tienda o a nosotros; si nos escribes, trasladaremos tu solicitud a la tienda y te ayudaremos a gestionarla.</p>'],
   ['datos','Qué datos tratamos','<h3>De las tiendas (usuarios de Tinbana)</h3><ul><li>Nombre, apellido, correo, teléfono, empresa, ubicación y foto de perfil.</li><li>Contraseña, guardada solo como resumen cifrado (hash); nunca la conocemos.</li><li>Credenciales de servicios que la tienda conecta (Dropi, proveedores de inteligencia artificial, WhatsApp Business de Meta, webhooks), guardadas cifradas en el servidor y nunca mostradas de nuevo.</li><li>Contenido que crea: productos seleccionados, landings, textos, imágenes y ofertas.</li><li>Datos de uso y seguridad: fecha del último acceso, direcciones IP para limitar intentos y prevenir abusos, y registros técnicos.</li></ul><h3>De los clientes de las tiendas</h3><ul><li>Nombre, teléfono, correo (si lo da), dirección, ciudad y departamento de entrega.</li><li>Detalle del pedido: producto, cantidad, precio, variante, notas y estado del envío.</li><li>Si la tienda usa ventas por WhatsApp: número de WhatsApp, nombre de perfil, mensajes de la conversación, estados de entrega y, cuando aplique, el anuncio desde el que llegó.</li></ul><p>No pedimos datos sensibles (salud, origen étnico, orientación, datos biométricos, etc.) ni datos de pago: Tinbana no procesa pagos con tarjeta.</p>'],
   ['finalidades','Para qué los usamos','<ul><li>Crear y administrar la cuenta, verificar el correo, recuperar el acceso y mantener la sesión segura.</li><li>Prestar el servicio: mostrar el catálogo, publicar landings, recibir consultas y pedidos, cotizar envíos y enviar las órdenes a Dropi cuando la tienda lo decide.</li><li>Atender conversaciones de WhatsApp de la tienda, incluida la respuesta con asistentes de inteligencia artificial cuando la tienda los activa, y avisar al cliente sobre su pedido.</li><li>Enviar correos de servicio (verificación, recuperación de contraseña y avisos de pedidos).</li><li>Aplicar planes y límites, prevenir fraudes y abusos, y cumplir obligaciones legales.</li><li>Atender consultas, reclamos y solicitudes de derechos.</li></ul><p>No vendemos datos personales ni los usamos para publicidad de terceros.</p>'],
   ['terceros','Con quién los compartimos','<p>Solo compartimos lo necesario para prestar el servicio, y casi siempre porque la tienda conectó o activó ese servicio:</p><ul><li><strong>Dropi</strong>: datos del pedido y de entrega, cuando la tienda envía una orden o consulta el envío.</li><li><strong>Meta (WhatsApp Business Platform)</strong>: mensajes y número del cliente, cuando la tienda conecta su número de WhatsApp.</li><li><strong>Proveedores de inteligencia artificial</strong> que la tienda conecta (OpenAI o Anthropic): el contenido necesario para generar textos de landings o responder conversaciones.</li><li><strong>Webhooks y CRM</strong> que la tienda configura (por ejemplo, GoHighLevel): los datos de la consulta o pedido que la tienda decide reenviar.</li><li><strong>Proveedores de infraestructura</strong>: alojamiento web y base de datos, y envío de correos.</li><li><strong>Autoridades</strong>, cuando una norma o una orden lo exija.</li></ul><p>Algunos de estos proveedores están fuera de Colombia, lo que implica una transferencia o transmisión internacional de datos. Solo lo hacemos para las finalidades descritas, con proveedores que ofrecen medidas de seguridad adecuadas y conforme a la ley.</p>'],
   ['autorizacion','Autorización','<p>Al crear una cuenta, la tienda autoriza el tratamiento de sus datos según esta política. Cada tienda es responsable de obtener la autorización de sus clientes (por ejemplo, en sus landings y en sus conversaciones de WhatsApp) y de informarles de su propia política, y de contar con su permiso antes de enviarles mensajes de seguimiento o promoción.</p>'],
   ['derechos','Tus derechos','<p>Como titular de los datos puedes:</p><ul><li>Conocer, actualizar y rectificar tus datos.</li><li>Pedir prueba de la autorización que otorgaste.</li><li>Saber qué uso se ha dado a tus datos.</li><li>Revocar la autorización o pedir que se eliminen, cuando no exista un deber legal o contractual de conservarlos.</li><li>Acceder gratis a tus datos.</li><li>Presentar quejas ante la Superintendencia de Industria y Comercio (SIC), después de haber acudido a nosotros.</li></ul>'],
   ['solicitudes','Cómo ejercerlos','<p>Escríbenos a '.$c.' indicando tu nombre, el dato o la cuenta a la que se refiere tu solicitud, lo que pides y un medio para responderte. Podemos pedirte información para verificar tu identidad.</p><ul><li><strong>Consultas</strong>: respondemos en máximo 10 días hábiles, prorrogables 5 días hábiles más si es necesario (te avisaremos el motivo).</li><li><strong>Reclamos</strong> (corrección, actualización, supresión o incumplimiento): respondemos en máximo 15 días hábiles, prorrogables 8 días hábiles más si es necesario.</li></ul><p>Las tiendas pueden además actualizar su perfil desde el panel y eliminar sus contenidos, números conectados y credenciales en cualquier momento.</p>'],
   ['eliminacion','Eliminación de datos','<p>Para eliminar tu cuenta de Tinbana o los datos que una tienda tiene de ti (incluidos los de una conversación de WhatsApp), escribe a '.$c.' con el asunto «Eliminar mis datos» e indica tu correo o número de teléfono. Confirmaremos la eliminación al terminar. Podemos conservar lo que la ley nos obligue a guardar (por ejemplo, información contable o de un pedido despachado) durante el tiempo exigido.</p><p>Si quieres dejar de recibir mensajes de una tienda por WhatsApp, puedes decírselo en la misma conversación o bloquear el número; también puedes pedírnoslo y lo trasladaremos.</p>'],
   ['conservacion','Cuánto tiempo los conservamos','<p>Mientras la cuenta esté activa y sea necesario para las finalidades descritas. Al eliminarse una cuenta o un dato, lo borramos o anonimizamos, salvo lo que debamos conservar por obligación legal, para atender reclamos o para defender derechos. Los registros técnicos se conservan por periodos cortos.</p>'],
   ['seguridad','Seguridad','<p>Usamos conexiones cifradas (HTTPS), contraseñas protegidas con hash, credenciales de terceros cifradas en el servidor, separación estricta de los datos de cada tienda, protección contra solicitudes falsificadas (CSRF), límites de intentos y verificación de firma en los mensajes que recibimos de Meta. Ningún sistema es infalible: si ocurre un incidente que afecte tus datos, lo informaremos a quien corresponda según la ley.</p>'],
   ['cookies','Cookies y almacenamiento local','<p>Usamos una cookie técnica de sesión, necesaria para mantenerte conectado y proteger tu cuenta, y guardamos en tu navegador preferencias como el tema claro u oscuro. No usamos cookies de publicidad ni de seguimiento de terceros en el panel. Las landings de cada tienda pueden incluir herramientas que la tienda añada por su cuenta, bajo su responsabilidad.</p>'],
   ['menores','Menores de edad','<p>Tinbana está dirigida a mayores de edad. No recogemos a sabiendas datos de menores; si detectamos una cuenta de un menor, la eliminaremos.</p>'],
   ['cambios','Cambios en esta política','<p>Podemos actualizar esta política. Publicaremos la versión vigente en esta página con su fecha y, si el cambio es importante, avisaremos a las tiendas por correo o en el panel.</p>'],
  ]);
 }

 public static function terms(): string {
  $o=self::owner();$n=Support::escape($o['name']);$c=self::contact($o);
  return self::page('terminos','Términos y condiciones de uso','Las reglas para usar Tinbana: qué ofrece la plataforma, qué esperamos de cada tienda y los límites de nuestra responsabilidad.',[
   ['aceptacion','Aceptación','<p>Estos términos regulan el uso de la plataforma Tinbana, prestada por '.$n.'. Al crear una cuenta o usar la plataforma aceptas estos términos y la <a href="/privacidad">Política de privacidad</a>. Si no estás de acuerdo, no uses el servicio.</p>'.self::identity($o)],
   ['servicio','Qué es Tinbana','<p>Tinbana es una plataforma para tiendas de dropshipping que permite, entre otras funciones, explorar el catálogo de Dropi con la cuenta propia de la tienda, crear y publicar landings (también con ayuda de inteligencia artificial), recibir consultas y pedidos, cotizar envíos, enviar órdenes a Dropi, gestionar ofertas y atender clientes por WhatsApp. Las funciones disponibles dependen del plan asignado a cada cuenta y pueden evolucionar con el tiempo.</p><p>Tinbana no es Dropi, Meta, OpenAI, Anthropic ni GoHighLevel, ni actúa en su nombre. No vende productos al consumidor final ni procesa pagos.</p>'],
   ['cuenta','Tu cuenta','<ul><li>Debes ser mayor de edad y dar información veraz.</li><li>Eres responsable de guardar tu contraseña y de lo que ocurra con tu cuenta. Avísanos si sospechas un acceso no autorizado.</li><li>Puedes cerrar tu cuenta cuando quieras escribiendo a '.$c.'.</li></ul>'],
   ['planes','Planes, límites y precios','<p>Cada cuenta tiene un plan con funciones y límites (por ejemplo, número de landings o de conversaciones atendidas por inteligencia artificial). Las condiciones económicas, si las hay, se informarán antes de su aplicación. Podemos ajustar planes y límites avisando con antelación razonable; los cambios no afectan lo ya pagado durante el periodo en curso.</p>'],
   ['obligaciones','Responsabilidades de la tienda','<p>La tienda es la vendedora frente a sus clientes y es responsable de:</p><ul><li>La veracidad de los productos, precios, promociones, tiempos de entrega y garantías que publica, y el cumplimiento del Estatuto del Consumidor (Ley 1480 de 2011), incluido el derecho de retracto y la garantía legal cuando apliquen.</li><li>Obtener la autorización de sus clientes para tratar sus datos y para escribirles, y atender sus solicitudes, conforme a la Ley 1581 de 2012.</li><li>Cumplir las políticas de los servicios que conecta: términos de Dropi, políticas de WhatsApp Business y de comercio de Meta, y condiciones de los proveedores de inteligencia artificial.</li><li>Revisar los pedidos antes de enviarlos a Dropi y el contenido generado por inteligencia artificial antes de publicarlo.</li><li>Tener los derechos sobre los textos, imágenes y marcas que sube.</li></ul>'],
   ['prohibido','Usos no permitidos','<ul><li>Vender productos ilegales, falsificados, peligrosos o restringidos, o publicar contenido engañoso, ofensivo o que infrinja derechos de terceros.</li><li>Enviar mensajes no solicitados o masivos (spam) o contactar a personas que pidieron no ser contactadas.</li><li>Intentar acceder a datos de otras tiendas, vulnerar la seguridad, saturar el servicio o usarlo de forma automatizada no autorizada.</li><li>Revender o sublicenciar la plataforma sin autorización.</li></ul><p>Si detectamos un uso no permitido podemos suspender o cerrar la cuenta, de ser posible con aviso previo y explicando el motivo.</p>'],
   ['terceros','Servicios de terceros','<p>Varias funciones dependen de servicios de terceros que la tienda conecta con sus propias credenciales (Dropi, Meta, proveedores de inteligencia artificial, webhooks y CRM). Su disponibilidad, precios, tarifas y decisiones (por ejemplo, la aprobación de plantillas de WhatsApp, cotizaciones de envío o estados de las órdenes) no dependen de nosotros. Los cobros que esos servicios hagan a la tienda son responsabilidad de la tienda.</p>'],
   ['ia','Inteligencia artificial','<p>El contenido y las respuestas generados con inteligencia artificial pueden contener errores. La tienda debe revisarlos, mantener fichas de producto correctas y supervisar las conversaciones. Tinbana permite pasar una conversación a una persona y revisar los pedidos antes de enviarlos, pero la decisión final es de la tienda.</p>'],
   ['contenido','Contenido y propiedad intelectual','<p>La tienda conserva los derechos sobre su contenido y nos autoriza a alojarlo, procesarlo y mostrarlo solo para prestar el servicio. La plataforma, su diseño, código, marca y logotipos de Tinbana nos pertenecen y no pueden copiarse ni usarse sin autorización.</p>'],
   ['disponibilidad','Disponibilidad del servicio','<p>Trabajamos para que la plataforma funcione de forma continua y segura, pero puede haber interrupciones por mantenimiento, fallas o causas ajenas a nosotros. Recomendamos conservar copia de la información importante para tu negocio.</p>'],
   ['responsabilidad','Limitación de responsabilidad','<p>En la medida en que la ley lo permita, no respondemos por pérdidas de ventas, lucro cesante ni daños indirectos derivados del uso de la plataforma, de fallas de servicios de terceros o de decisiones de la tienda. Nada de lo anterior limita los derechos que la ley reconoce y que no pueden renunciarse.</p>'],
   ['terminacion','Terminación','<p>Puedes dejar de usar Tinbana y pedir el cierre de tu cuenta en cualquier momento. Al cerrarla, eliminaremos tus datos según la <a href="/privacidad">Política de privacidad</a>. Las órdenes ya enviadas a Dropi y los mensajes ya entregados no se deshacen.</p>'],
   ['cambios','Cambios en estos términos','<p>Podemos modificar estos términos. Publicaremos la versión vigente aquí con su fecha y avisaremos de los cambios importantes. Si sigues usando la plataforma después de la fecha de vigencia, se entiende que los aceptas.</p>'],
   ['ley','Ley aplicable y contacto','<p>Estos términos se rigen por las leyes de la República de Colombia. Antes de acudir a las autoridades competentes, intentaremos resolver cualquier diferencia de forma directa. Para preguntas, escríbenos a '.$c.'.</p>'],
  ]);
 }

 /** @param list<array{0:string,1:string,2:string}> $sections */
 private static function page(string $slug,string $title,string $lead,array $sections): string {
  $t=Support::escape($title);$toc='';$body='';
  foreach($sections as $i=>[$id,$h,$html]){$num=$i+1;$toc.='<li><a href="#'.$id.'">'.Support::escape($h).'</a></li>';$body.='<section id="'.$id.'"><h2><span>'.str_pad((string)$num,2,'0',STR_PAD_LEFT).'</span>'.Support::escape($h).'</h2>'.$html.'</section>';}
  $other=$slug==='privacidad'?['/terminos','Términos y condiciones']:['/privacidad','Política de privacidad'];
  return '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.$t.' · Tinbana</title><meta name="description" content="'.Support::escape($lead).'"><meta name="robots" content="index,follow"><link rel="icon" href="/brand/tinvana-origami.svg"><link rel="stylesheet" href="/brand/fonts/montserrat.css"><style>'.self::css().'</style></head><body>'
   .'<header class="legal-top"><div class="legal-wrap"><a class="legal-logo" href="/login" aria-label="Tinbana"><img src="/brand/tinvana-original.svg" alt="Tinbana" width="150" height="36"></a><nav aria-label="Documentos legales"><a href="/privacidad"'.($slug==='privacidad'?' aria-current="page"':'').'>Privacidad</a><a href="/terminos"'.($slug==='terminos'?' aria-current="page"':'').'>Términos</a></nav></div></header>'
   .'<div class="legal-hero"><div class="legal-wrap"><span class="legal-eyebrow">Legal</span><h1>'.$t.'</h1><p>'.Support::escape($lead).'</p><p class="legal-date">Última actualización: '.self::UPDATED.'</p></div></div>'
   .'<div class="legal-wrap legal-grid"><aside class="legal-toc"><strong>Contenido</strong><ol>'.$toc.'</ol></aside><main class="legal-body">'.$body
   .'<p class="legal-next">Consulta también nuestra <a href="'.$other[0].'">'.$other[1].'</a>.</p></main></div>'
   .'<footer class="legal-foot"><div class="legal-wrap"><span>© '.date('Y').' Tinbana</span><span><a href="/privacidad">Privacidad</a> · <a href="/terminos">Términos</a> · <a href="/login">Iniciar sesión</a></span></div></footer></body></html>';
 }
 private static function css(): string {
  return ':root{--o:#FF6A00;--ink:#1E1E1E;--muted:#5d5550;--bg:#FFF8F1;--card:#fff;--line:#FFE0CD;--soft:#fff1e5;color-scheme:light}'
  .'@media (prefers-color-scheme:dark){:root{--ink:#f4ede7;--muted:#b9aea6;--bg:#161210;--card:#1f1a17;--line:#3a2c24;--soft:#2a1f19;color-scheme:dark}.legal-logo img{content:url(/brand/tinvana-light.svg)}}'
  .'*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:84px}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.7 Montserrat,system-ui,sans-serif;-webkit-font-smoothing:antialiased}'
  .'a{color:var(--o);text-underline-offset:3px}a:focus-visible{outline:2px solid var(--o);outline-offset:2px;border-radius:4px}'
  .'.legal-wrap{max-width:1120px;margin:0 auto;padding:0 20px}'
  .'.legal-top{position:sticky;top:0;z-index:2;background:color-mix(in srgb,var(--bg) 88%,transparent);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}.legal-top .legal-wrap{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:64px}'
  .'.legal-logo img{display:block;width:150px;height:36px;object-fit:contain}.legal-top nav{display:flex;gap:4px}.legal-top nav a{padding:8px 14px;border-radius:999px;color:var(--ink);text-decoration:none;font-weight:600;font-size:14px}.legal-top nav a[aria-current]{background:var(--o);color:#fff}'
  .'.legal-hero{padding:56px 0 36px;background:radial-gradient(600px 260px at 85% 0,color-mix(in srgb,var(--o) 16%,transparent),transparent)}.legal-eyebrow{font-size:13px;font-weight:700;color:var(--o);text-transform:uppercase;letter-spacing:.08em}'
  .'.legal-hero h1{margin:8px 0 12px;font-size:clamp(30px,5vw,48px);line-height:1.1;letter-spacing:-.035em}.legal-hero p{margin:0;max-width:680px;color:var(--muted);font-size:18px}.legal-hero .legal-date{margin-top:14px;font-size:14px}'
  .'.legal-grid{display:grid;grid-template-columns:250px minmax(0,1fr);gap:40px;padding-bottom:64px}'
  .'.legal-toc{position:sticky;top:88px;align-self:start;padding:18px;border:1px solid var(--line);border-radius:18px;background:var(--card)}.legal-toc strong{font-size:13px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}.legal-toc ol{margin:10px 0 0;padding-left:20px;font-size:14px;line-height:1.5}.legal-toc li{margin:6px 0}.legal-toc a{color:var(--ink);text-decoration:none}.legal-toc a:hover{color:var(--o)}'
  .'.legal-body section{padding:26px 28px;margin-bottom:16px;border:1px solid var(--line);border-radius:22px;background:var(--card)}.legal-body h2{display:flex;align-items:baseline;gap:12px;margin:0 0 12px;font-size:22px;letter-spacing:-.02em}.legal-body h2 span{font-size:14px;color:var(--o);font-variant-numeric:tabular-nums}'
  .'.legal-body h3{margin:18px 0 6px;font-size:16px}.legal-body p{margin:0 0 12px}.legal-body ul{margin:0 0 12px;padding-left:22px}.legal-body li{margin:6px 0}.legal-body>section>:last-child{margin-bottom:0}'
  .'.legal-identity{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;margin:14px 0 0;padding:16px;border-radius:14px;background:var(--soft)}.legal-identity dt{font-size:12px;color:var(--muted)}.legal-identity dd{margin:2px 0 0;font-weight:600;overflow-wrap:anywhere}'
  .'.legal-next{padding:4px 4px 0;color:var(--muted)}.legal-foot{border-top:1px solid var(--line);font-size:14px;color:var(--muted)}.legal-foot .legal-wrap{display:flex;flex-wrap:wrap;justify-content:space-between;gap:10px;padding-top:22px;padding-bottom:22px}'
  .'@media (max-width:860px){.legal-grid{grid-template-columns:1fr;gap:20px}.legal-toc{position:static}.legal-body section{padding:20px}.legal-hero{padding:36px 0 24px}.legal-logo img{width:120px}}'
  .'@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}';
 }
}
